const rows = $('Read Engine Config').all().map(i => i.json).filter(r => r && r.config_key);
const cfg = {};
let lockRow = null;
for (const r of rows) { cfg[r.config_key] = r.config_value; if (r.config_key === 'engine_lock') lockRow = r; }
const num = (k, d) => { const v = parseFloat(cfg[k]); return isNaN(v) ? d : v; };
const settings = {
  max_records: Math.min(20, Math.max(1, Math.round(num('max_records_per_run', 5)))),
  budget: num('daily_api_budget_usd', 3),
  max_retries: Math.max(1, Math.round(num('max_retries', 3))),
  retry_base: num('retry_base_minutes', 10),
  lock_timeout: num('lock_timeout_minutes', 20),
  cost_search: num('cost_search_usd', 0.005),
  cost_scrape: num('cost_scrape_usd', 0.002),
  cost_ai: num('cost_ai_usd', 0.003),
  enabled: String(cfg.engine_enabled == null ? 'true' : cfg.engine_enabled).toLowerCase() !== 'false'
};
const logs = $input.all().map(i => i.json).filter(r => r && r.execution_id);
const spend = logs.reduce((a, r) => a + (Number(r.api_cost) || 0), 0);
const now = Date.now();
let proceed = true;
let reason = 'OK';
if (!lockRow) { proceed = false; reason = 'engine_lock row missing in MC_Config'; }
else if (!settings.enabled) { proceed = false; reason = 'Engine disabled (engine_enabled=false)'; }
else if (spend >= settings.budget) { proceed = false; reason = 'Daily API budget reached: $' + spend.toFixed(3); }
else if (lockRow.config_value) {
  const lockedAt = lockRow.locked_at ? new Date(lockRow.locked_at).getTime() : 0;
  if (now - lockedAt < settings.lock_timeout * 60000) { proceed = false; reason = 'Run ' + lockRow.config_value + ' still holds the lock'; }
}
return [{ json: { proceed, reason, settings, spend_today: Number(spend.toFixed(4)), execution_id: String($execution.id), started_at: new Date().toISOString() } }];

const ctx = $('Check Lock & Budget').first().json;
const now = Date.now();
const rows = $input.all().map(i => i.json).filter(r => r && r.search_id);
const eligible = rows.filter(r => {
  if (r.status === 'PENDING') return true;
  if (r.status === 'RETRY') return !r.next_retry_at || new Date(r.next_retry_at).getTime() <= now;
  if (r.status === 'RUNNING') return !r.last_run || (now - new Date(r.last_run).getTime()) > ctx.settings.lock_timeout * 60000;
  return false;
});
eligible.sort((a, b) => (Number(a.priority) || 999) - (Number(b.priority) || 999));
if (!eligible.length) return [{ json: { has_search: false, queue_rows_seen: rows.length } }];
const s = eligible[0];
const area = String(s.location || '').trim();
const city = String(s.city || area).trim();
const place = area.toLowerCase().indexOf(city.toLowerCase()) >= 0 ? area : area + ', ' + city;
return [{ json: {
  has_search: true,
  search_id: s.search_id,
  industry: s.industry || '',
  search_keyword: s.search_keyword || '',
  area,
  city,
  region: s.region || '',
  target_customer: s.target_customer || '',
  retry_count: Number(s.retry_count) || 0,
  previous_status: s.status,
  query: s.search_keyword + ' in ' + place
} }];

const s = $('Pick Next Search').first().json;
const ctx = $('Check Lock & Budget').first().json;
const res = ($input.first() && $input.first().json) || {};
