}
const BLOCK = ['justdial.com','indiamart.com','sulekha.com','asklaila.com','tradeindia.com','exportersindia.com','yellowpages','yelp.','zomato.com','swiggy.com','practo.com','lybrate.com','magicbricks.com','99acres.com','housing.com','nobroker.in','commonfloor.com','squareyards.com','urbancompany.com','facebook.com','instagram.com','linkedin.com','youtube.com','twitter.com','x.com','wikipedia.org','quora.com','reddit.com','glassdoor','ambitionbox.com','naukri.com','indeed.','crunchbase.com','tracxn.com','zaubacorp.com','tofler.in','google.','tripadvisor','booking.com','makemytrip.com','goibibo.com','agoda.com','medium.com','builtin','revenuebase.ai','smergers.com','scribd.com','clutch.co','goodfirms.co','designrush.com','sortlist','f6s.com','wellfound.com','startupindia.gov.in','yourstory.com','inc42.com','economictimes','timesofindia','thehindu','deccanherald','hindustantimes','ndtv','moneycontrol','business-standard','livemint','urbanpro.com','shiksha.com','collegedunia.com','careers360.com','cardekho.com','carwale.com','zigwheels.com','wedmegood.com','weddingwire','weddingbazaar','fresha.com','magicpin','dineout','eazydiner','nearbuy','justdial','threebestrated','top10','bestinbangalore','mouthshut.com','grotal.com','helloleads','mapsofindia','wikimapia','zaubacorp','companiesinn','thecompanycheck','pinterest.','apps.apple.com','play.google.com','amazon.','flipkart.com','dial4trade','getit.in','nearfox','yappe.in','bizdirectory','listings','indiacustomercare','customercare','helpline','bbmp','ksrtc','nhp.gov','india.gov','mygov','wikiwand','slideshare','issuu','academia.edu','researchgate'];
const GOV = /(^|\.)(gov|nic|gov\.in|nic\.in|mil)(\.|$)|\.gov\.in$|\.nic\.in$|karnataka\.gov|\.res\.in$/i;
const DOC = /\.(pdf|docx?|xlsx?|pptx?|txt)(\?|$)/i;
const LISTICLE = /(^|\s)(top|best)\s+\d+|\blist of\b|near me|\d+\+?\s+(best|top|companies|firms|agencies|clinics|listings|options|places)|\bdirectory\b|\branked\b/i;
const AGG_TITLE = /\b(find|explore|browse|compare|listing|listings|dataset|reviews of|near me|list|empanelled|search for)\b/i;
const rootOf = h => { const p = h.split('.'); if (p.length >= 3 && /^(co|org|net|ac|edu|gov|firm|gen|ind)$/.test(p[p.length - 2])) return p[p.length - 3]; return p.length >= 2 ? p[p.length - 2] : p[0]; };
const LIST_PATH = /\/(blog|blogs|articles?|news|list|lists|top-|best-|category|tag|directory)\b/i;
const strip = t => String(t || '').replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
const hostOf = u => { const m = String(u || '').match(/^https?:\/\/([^\/:?#]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
const blocked = h => GOV.test(h) || BLOCK.some(b => h === b || h.endsWith('.' + b) || h.indexOf(b) >= 0);
const originOf = u => { const m = String(u || '').match(/^(https?:\/\/[^\/?#]+)/i); return m ? m[1] + '/' : ''; };
const pathOf = u => String(u || '').replace(/^https?:\/\/[^\/?#]+/i, '') || '/';
const phoneRe = /(?:\+91[\s-]?|0)?[6-9]\d{4}[\s-]?\d{5}|0?80[\s-]?\d{4}[\s-]?\d{4}/g;
const emailRe = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig;
const digits = p => String(p || '').replace(/\D/g, '').slice(-10);
const norm = t => String(t || '').toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');
const hash = str => { let h = 5381; for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0; return Math.abs(h).toString(36).toUpperCase(); };
function pickName(title, host) {
  const root = host.split('.')[0];
  const parts = strip(title).split(/\s[|\u2013\u2014-]\s|:\s/).map(p => p.trim()).filter(Boolean);
  let best = parts[0] || host;
  let bestScore = -1;
  for (const p of parts) {
    const n = norm(p);
    let sc = 0;
    if (n && root && (n.indexOf(root) >= 0 || root.indexOf(n.slice(0, 6)) >= 0)) sc += 3;
    if (p.length <= 60) sc += 1;
    if (/best|top|leading|no\.?\s?1|services in|company in/i.test(p)) sc -= 2;
    if (sc > bestScore) { bestScore = sc; best = p; }
  }
