}
const web = (res.web && res.web.results) || [];
const out = [];
const seen = new Set();
let totalFound = 0;
for (const r of web) {
  const url = r.url || '';
  const host = hostOf(url);
  if (!host || DOC.test(url)) continue;
  const title = strip(r.title);
  const loc = r.location || null;
  const snippetText = strip([r.description || ''].concat(r.extra_snippets || []).join(' '));
  let websiteUrl = '';
  let opportunityHint = '';
  let confidence = 'MEDIUM';
  let name = '';
  if (blocked(host)) {
    // Single-business directory listings (no official site in this result) are kept as research candidates.
    const isJdListing = host.indexOf('justdial.com') >= 0 && /_BZDET/i.test(url);
    if (!isJdListing) continue;
    name = strip(title.split(/ in | - |\|/i)[0]);
    websiteUrl = '';
    opportunityHint = 'NO_WEBSITE_IN_SEARCH';
    confidence = 'LOW';
  } else {
    const path = pathOf(url);
    if (LISTICLE.test(title) || LIST_PATH.test(path) || AGG_TITLE.test(title)) continue;
    const root = rootOf(host);
    const brandMatch = root.length >= 4 && norm(title + ' ' + ((r.profile && r.profile.name) || '')).indexOf(norm(root)) >= 0;
    if (!loc && !brandMatch) continue;
    name = loc && loc.title ? strip(loc.title) : pickName(title, host);
    if (!name || /^https?:\/\//i.test(name)) name = host.split('.')[0];
    websiteUrl = originOf(url);
  }
  totalFound++;
  const contact = (loc && loc.contact) || {};
  const phoneFromText = (snippetText.match(phoneRe) || [])[0] || '';
  const phone = contact.telephone || phoneFromText;
  const emails = (contact.email ? [contact.email] : []).concat(snippetText.match(emailRe) || []);
  const pa = (loc && loc.postal_address) || {};
  let address = pa.displayAddress || '';
  if (!address) {
