  out.push({
    lead_id: 'MC-' + hash(dedupeIdentity),
    business_name: name || host,
    website_url: websiteUrl,
    domain_key: domainKey,
    phone_key: phoneKey,
    name_city_key: nameCityKey,
    phone: phone,
    public_email: emails[0] || '',
    address: address,
    city: s.city,
    area: s.area,
    industry: s.industry,
    search_id: s.search_id,
    target_customer: s.target_customer,
    evidence_url: url,
    source_snippet: snippetText.slice(0, 900),
    opportunity_hint: opportunityHint,
    discovery_confidence: confidence,
    rating: loc && loc.rating ? String(loc.rating.ratingValue || '') + ' (' + String(loc.rating.reviewCount || 0) + ' reviews)' : '',
