const s = $('Pick Next Search').first().json;
const ctx = $('Check Lock & Budget').first().json;
const err = String($input.first().json.error_message || 'Unknown search error').slice(0, 400);
const attempts = (Number(s.retry_count) || 0) + 1;
const failed = attempts >= ctx.settings.max_retries;
