  api_cost: total,
  remarks: 'query="' + s.query + '"; raw_results=' + (norm.raw_results || 0) + '; processed=' + outs.length + (capped ? ' (capped at max_records_per_run)' : '') + '; high=' + high + '; no_website=' + noSite + '; cost_breakdown: search=' + costSearch.toFixed(4) + ';scrape=' + costScrape.toFixed(4) + ';ai=' + costAi.toFixed(4)
} }];

const biz = $('Current Business').first().json;
const raw = ($('Scrape Website').first() || {}).json || {};
const psi = ($input.first() || {}).json || {};
const data = raw.data || raw;
const meta = data.metadata || raw.metadata || {};
const md = String(data.markdown || '');
const html = String(data.html || data.rawHtml || '');
const links = Array.isArray(data.links) ? data.links : [];
const scrapeError = raw.error ? (typeof raw.error === 'string' ? raw.error : (raw.error.message || 'scrape error')) : (raw.success === false ? 'scrape failed' : '');
const statusCode = Number(meta.statusCode || 0);
const finalUrl = String(meta.url || meta.sourceURL || biz.website_url);
const hostOf = u => { const m = String(u || '').match(/^https?:\/\/([^\/:?#]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
const yearNow = new Date().getFullYear();
const issues = [];
const observations = [];
const improvements = [];
let websiteStatus = 'WEBSITE_AVAILABLE';
if (scrapeError || (statusCode && statusCode >= 400) || (!md && !html)) websiteStatus = 'WEBSITE_INACCESSIBLE';
else if (/coming soon|under construction|launching soon|site is being built|website is under maintenance|domain (is )?for sale|this domain is parked|buy this domain/i.test(md.slice(0, 4000))) websiteStatus = 'UNDER_CONSTRUCTION';
else {
  const a = hostOf(biz.website_url), b = hostOf(finalUrl);
  if (a && b && a !== b && !b.endsWith('.' + a) && !a.endsWith('.' + b)) websiteStatus = 'REDIRECTS_ELSEWHERE';
}
const ok = websiteStatus !== 'WEBSITE_INACCESSIBLE';
const ssl = !ok ? 'UNKNOWN' : (/^https:/i.test(finalUrl) ? 'HTTPS' : 'NO HTTPS');
const viewport = String(meta.viewport || '') || ((html.match(/<meta[^>]+name=["']viewport["'][^>]*>/i) || [])[0] || '');
let mobile = 'UNKNOWN';
