const lh = psi.lighthouseResult || null;
const perf = lh && lh.categories && lh.categories.performance && lh.categories.performance.score != null ? Math.round(lh.categories.performance.score * 100) : null;
const seoScore = lh && lh.categories && lh.categories.seo && lh.categories.seo.score != null ? Math.round(lh.categories.seo.score * 100) : null;
const psiNote = lh ? '' : (psi.error ? 'PageSpeed unavailable: ' + String(psi.error.message || psi.error).slice(0, 120) : 'PageSpeed not returned');
