  http_status: statusCode ? String(statusCode) : (scrapeError ? 'ERROR' : 'UNKNOWN'),
  ssl,
  mobile_responsive: mobile,
  page_speed_score: perf != null ? String(perf) : 'UNKNOWN',
  seo_score: seoScore != null ? String(seoScore) : 'UNKNOWN',
  seo_title: title || (ok ? 'MISSING' : 'UNKNOWN'),
  meta_description: desc || (ok ? 'MISSING' : 'UNKNOWN'),
  h1: h1 || (ok ? 'MISSING' : 'UNKNOWN'),
  broken_links: 'NOT TESTED (link checking not enabled)',
  cta_status: ok ? (cta ? 'CTA FOUND' : 'NO CTA DETECTED') : 'UNKNOWN',
  contact_form_status: ok ? (hasForm ? 'FORM FOUND' : 'NO FORM ON HOMEPAGE') : 'UNKNOWN',
  booking_option: ok ? (booking ? 'FOUND' : 'NOT FOUND') : 'UNKNOWN',
  whatsapp: ok ? (whatsapp ? 'FOUND' : 'NOT FOUND') : 'UNKNOWN',
  facebook_url: facebook, instagram_url: instagram, linkedin_url: linkedin, youtube_url: youtube, twitter_url: twitter,
  page_email: pageEmails[0] || '',
  page_phone: pagePhones[0] || '',
  copyright_year: copyrightYear ? String(copyrightYear) : 'NOT FOUND',
  outdated_indicators: outdated,
  issues,
  improvements: Array.from(new Set(improvements)),
  ux_observations: observations.join('; '),
  audit_confidence: confidence,
  scraped: 1,
  homepage_excerpt: md.replace(/\s+/g, ' ').slice(0, 1500)
